import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CZxGLIO_.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Diagnose GooseForum startup, registration, proxy, MFA, storage and upgrade problems.","frontmatter":{"title":"Troubleshooting","description":"Diagnose GooseForum startup, registration, proxy, MFA, storage and upgrade problems."},"headers":[],"relativePath":"en/docs/gooseforum/troubleshooting/index.md","filePath":"en/docs/gooseforum/troubleshooting/index.md"}'),s={name:"en/docs/gooseforum/troubleshooting/index.md"};function i(n,e,d,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Record the version, working directory, database type, recent changes and error time before reviewing logs. Remove passwords, cookies, tokens, connection strings and email credentials before sharing diagnostics.</p><h2 id="startup-fails-or-the-forum-is-unexpectedly-empty" tabindex="-1">Startup fails or the forum is unexpectedly empty <a class="header-anchor" href="#startup-fails-or-the-forum-is-unexpectedly-empty" aria-label="Permalink to &quot;Startup fails or the forum is unexpectedly empty&quot;">​</a></h2><p>With systemd, inspect <code>systemctl status gooseforum</code> and <code>journalctl -u gooseforum -n 100 --no-pager</code>. Check occupied ports, TOML syntax, file permissions and database availability.</p><p>If the service starts with no old topics, check <code>WorkingDirectory</code>, the actual <code>config.toml</code>, the SQLite path or external database name. Do not keep registering, migrating or replacing data before confirming the correct database.</p><h2 id="registration-email-or-rate-limit-problems" tabindex="-1">Registration, email or rate-limit problems <a class="header-anchor" href="#registration-email-or-rate-limit-problems" aria-label="Permalink to &quot;Registration, email or rate-limit problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>New accounts cannot register</td><td>Registration switch, exact allowed-domain matching, SMTP configuration</td></tr><tr><td>First OAuth login fails</td><td>Valid upstream email, conflicts with existing accounts, registration policy</td></tr><tr><td>Users appear to share one IP</td><td>Proxy address in <code>server.trustedProxies</code></td></tr><tr><td>Test email works but settings do not</td><td>Tests use current form values; save them afterward</td></tr><tr><td>SMTP accepts email but it never arrives</td><td>Inbox, spam, provider delivery logs and bounces</td></tr><tr><td>Unverified account cannot sign in</td><td>Correct credentials can trigger resend, subject to cooldown and quotas</td></tr></tbody></table><p>Fix configuration and delivery before retrying. Repeated restarts to clear counters do not diagnose the problem. See <a href="./../security/">account security</a> for quota defaults.</p><h2 id="mfa-verification-fails" tabindex="-1">MFA verification fails <a class="header-anchor" href="#mfa-verification-fails" aria-label="Permalink to &quot;MFA verification fails&quot;">​</a></h2><p>Check server and phone clocks, reused codes and expired login challenges. A restart clears challenges, requiring a new login attempt.</p><p>If all enrolled users fail after an upgrade, first check whether <code>[app].secretKey</code> or the old <code>signingKey</code> changed. Restore the original value; a new key cannot decrypt existing data. Follow <a href="./../security/">recovery guidance</a> for a lost authenticator. Password reset does not remove MFA.</p><h2 id="images-or-attachments-fail" tabindex="-1">Images or attachments fail <a class="header-anchor" href="#images-or-attachments-fail" aria-label="Permalink to &quot;Images or attachments fail&quot;">​</a></h2><p>For database storage, check the connection and file records. For S3, separately inspect the server endpoint, credentials, bucket, browser-facing publicUrl and object permissions.</p><p>For direct uploads, inspect the presigned <code>PUT</code> in browser network tools. Bucket CORS must allow the site origin, <code>PUT</code> and <code>Content-Type</code>. Timeouts also require checking application HTTP timeouts, file-size rules and proxy limits.</p><h2 id="inconsistent-pages-after-deployment" tabindex="-1">Inconsistent pages after deployment <a class="header-anchor" href="#inconsistent-pages-after-deployment" aria-label="Permalink to &quot;Inconsistent pages after deployment&quot;">​</a></h2><p>Confirm frontend and backend belong to the same build, the running executable was replaced, and the proxy is not retaining stale HTML or status responses. Save drafts before refreshing. Rebuilding frontend files alone does not update resources embedded in an old binary.</p><h2 id="administrator-account-recovery" tabindex="-1">Administrator account recovery <a class="header-anchor" href="#administrator-account-recovery" aria-label="Permalink to &quot;Administrator account recovery&quot;">​</a></h2><p>A server administrator can use these commands from the <strong>original working directory</strong>. <code>42</code> is a placeholder user ID and must be checked first:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-user-admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-user-password</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;REPLACE_WITH_A_NEW_PASSWORD&#39;</span></span></code></pre></div><p>Run only the operation required and replace the example password. Command-line passwords may appear in shell history and process arguments; use a controlled maintenance terminal. A separate CLI password change can take up to 15 seconds to invalidate the running service&#39;s authentication cache. Neither command resets MFA.</p><h2 id="report-a-reproducible-issue" tabindex="-1">Report a reproducible issue <a class="header-anchor" href="#report-a-reproducible-issue" aria-label="Permalink to &quot;Report a reproducible issue&quot;">​</a></h2><p>Include version or commit SHA, OS and CPU, database type, reproduction steps, expected/actual behavior and sanitized logs. For UI failures, include browser version and failed request status codes. Report at <a href="https://github.com/leancodebox/GooseForum/issues" target="_blank" rel="noreferrer">GooseForum Issues</a>.</p><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/app/console/cmd/user.go" target="_blank" rel="noreferrer">User commands</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/registration-controls.md" target="_blank" rel="noreferrer">Registration</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/two-factor-authentication.md" target="_blank" rel="noreferrer">MFA</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/configuration.md" target="_blank" rel="noreferrer">Configuration</a>。</p>`,24)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
